look.customCSS:
/* ───── 八角 · 墨金 · 第一批 ───── */
[data-wk="chat"]{background:url("data:image/svg+xml;base64,") 0 0/60px 60px,radial-gradient(ellipse at 50% 30%,#1F1B14,#12100D 70%) !important}
[data-wk="body"]{background:transparent !important}

/* 顶栏：墨底，下沿一条回纹金带，带下吊五只小金铃 */
[data-wk="chathead"]{background:linear-gradient(180deg,#0C0B09,#1D1A15) !important;border-bottom:none !important;box-shadow:none !important;position:relative !important;z-index:5 !important;overflow:visible !important;gap:6px !important}
[data-wk="chathead"]::after{content:"" !important;position:absolute !important;left:0 !important;right:0 !important;top:100% !important;height:12px !important;background:url("data:image/svg+xml;base64,") 0 0/24px 12px repeat-x !important;pointer-events:none !important}
[data-wk="chathead"]::before{content:"" !important;position:absolute !important;left:0 !important;right:0 !important;top:calc(100% + 11px) !important;height:26px !important;background:url("data:image/svg+xml;base64,") 10% 0/14px 22px no-repeat,url("data:image/svg+xml;base64,") 30% 0/14px 22px no-repeat,url("data:image/svg+xml;base64,") 50% 0/14px 22px no-repeat,url("data:image/svg+xml;base64,") 70% 0/14px 22px no-repeat,url("data:image/svg+xml;base64,") 90% 0/14px 22px no-repeat !important;pointer-events:none !important;transform-origin:50% 0 !important;animation:ogSway 3.2s ease-in-out infinite !important}
@keyframes ogSway{0%,100%{transform:translateX(0)}50%{transform:translateX(1.5px)}}
[data-wk="chathead"] + *:not([data-wk="body"]){margin-top:30px !important}
[data-wk="headink"],[data-wk="headink"] *{color:#EBD394 !important;letter-spacing:.06em !important}
[data-wk="headdim"]{color:#9C8B66 !important;white-space:nowrap !important}
[data-wk="chatback"] svg,[data-wk="headdim"] svg{stroke:#C9A45C !important}
[data-wk="chathead"] [data-wk="headink"] > [data-wk="headdim"]{display:none !important}
[data-wk="chathead"] [data-wk="headname"],[data-wk="chathead"] button:has(> [data-wk="headname"]){flex:1 1 auto !important;min-width:0 !important}
[data-wk="sameroom"],[data-wk="chatmore"]{width:30px !important;min-width:30px !important;height:30px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;background-color:transparent !important}
[data-wk="sameroom"]{background:url("data:image/svg+xml;base64,") center/28px no-repeat !important}
[data-wk="chatmore"]{background:url("data:image/svg+xml;base64,") center/28px no-repeat !important}
[data-wk="chatmore"] *,[data-wk="sameroom"] *{opacity:0 !important}

/* 头像：切成八角，外面一圈八角金框，四个斜角嵌金珠 */
button[data-wk="avatar"],span[data-wk="avatar"]{position:relative !important;overflow:visible !important;isolation:isolate !important;border-radius:0 !important;box-shadow:none !important}
button[data-wk="avatar"] > *,span[data-wk="avatar"] > *,img[data-wk="avatar"]{border-radius:0 !important;clip-path:polygon(29% 0,calc(100% - 29%) 0,100% 29%,100% calc(100% - 29%),calc(100% - 29%) 100%,29% 100%,0 calc(100% - 29%),0 29%) !important}
button[data-wk="avatar"]::before,span[data-wk="avatar"]:not([data-halo])::before{content:"" !important;position:absolute !important;inset:-12% !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;z-index:2 !important;pointer-events:none !important;border:none !important;border-radius:0 !important}

/* 顶栏头像也套八角金框 */
[data-wk="chathead"] button:has(> img[data-wk="avatar"]){position:relative !important;overflow:visible !important}
[data-wk="chathead"] button:has(> img[data-wk="avatar"])::before{content:"" !important;position:absolute !important;left:-5px !important;top:50% !important;width:46px !important;height:46px !important;margin:-23px 0 0 0 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;z-index:2 !important;pointer-events:none !important}

/* 气泡：八角牌。外层画金边，::before 垫里面那块底（比外层缩进一圈） */
[data-wk="bubble"][data-kind="text"]{position:relative !important;isolation:isolate !important;border:none !important;border-radius:0 !important;clip-path:polygon(11px 0,calc(100% - 11px) 0,100% 11px,100% calc(100% - 11px),calc(100% - 11px) 100%,11px 100%,0 calc(100% - 11px),0 11px) !important;box-shadow:none !important;padding:11px 18px !important}
[data-wk="bubble"][data-kind="text"]::before{content:"" !important;position:absolute !important;inset:1.6px !important;clip-path:polygon(10.3px 0,calc(100% - 10.3px) 0,100% 10.3px,100% calc(100% - 10.3px),calc(100% - 10.3px) 100%,10.3px 100%,0 calc(100% - 10.3px),0 10.3px) !important;z-index:-1 !important;border:none !important;transform:none !important;width:auto !important;height:auto !important;top:1.6px !important;left:1.6px !important;right:1.6px !important;bottom:1.6px !important}
[data-wk="bubble"][data-kind="text"]::after{content:none !important}
/* 我的话：金箔牌，墨字，一道斜着的亮光 */
[data-wk="bubble"][data-kind="text"][data-me="1"]{background:#8A6A2E !important;color:#12100D !important;font-weight:600 !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::before{background:linear-gradient(115deg,transparent 0 30%,rgba(255,248,220,.45) 38%,transparent 46%),linear-gradient(180deg,#EBD394,#C9A45C 60%,#B48E45) !important}
/* 他的话：墨底金边，四角各钉一颗金铆钉 */
[data-wk="bubble"][data-kind="text"][data-me="0"]{background:#C9A45C !important;color:#F2E6C8 !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]::before{background:radial-gradient(circle at 10px 10px,#EBD394 1.8px,transparent 2.3px),radial-gradient(circle at calc(100% - 10px) 10px,#EBD394 1.8px,transparent 2.3px),radial-gradient(circle at 10px calc(100% - 10px),#EBD394 1.8px,transparent 2.3px),radial-gradient(circle at calc(100% - 10px) calc(100% - 10px),#EBD394 1.8px,transparent 2.3px),linear-gradient(180deg,#2A251D,#1D1A15) !important}

/* 时间：两道细金线夹两颗空心菱形 */
[data-wk="time"]{display:flex !important;justify-content:center !important}
[data-wk="time"] > span{display:inline-flex !important;align-items:center !important;justify-content:center !important;gap:8px !important;background:transparent !important;border:none !important;color:#C9A45C !important;font-family:serif !important;letter-spacing:.15em !important;font-size:12px !important;box-shadow:none !important;padding:2px 0 !important}
[data-wk="time"] > span::before,[data-wk="time"] > span::after{content:"" !important;display:inline-block !important;width:64px !important;height:10px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAxMiAxMic+PHBhdGggZD0nTTYgMS4yIEwxMC44IDYgTDYgMTAuOCBMMS4yIDZaJyBmaWxsPSdub25lJyBzdHJva2U9JyNDOUE0NUMnIHN0cm9rZS13aWR0aD0nMS4zJy8+PC9zdmc+") right center/10px 10px no-repeat,linear-gradient(#8A6A2E,#8A6A2E) left center/calc(100% - 14px) 1px no-repeat !important}
[data-wk="time"] > span::after{transform:scaleX(-1) !important}
/* 已读：一枚八角小金印刻「阅」；已送达只留一行小字 */
[data-wk="meta"]{color:#9C8B66 !important;font-size:10.5px !important;font-family:serif !important;letter-spacing:.08em !important}
[data-wk="meta"][data-read="1"]::before{content:"" !important;display:inline-block !important;width:15px !important;height:15px !important;margin-right:5px !important;vertical-align:-3px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="msg"][data-last="0"] [data-wk="meta"]{display:none !important}
[data-wk="bubble"][data-kind="typing"]{background:#1D1A15 !important;border:1.4px solid #C9A45C !important;border-radius:0 !important;clip-path:polygon(9px 0,calc(100% - 9px) 0,100% 9px,100% calc(100% - 9px),calc(100% - 9px) 100%,9px 100%,0 calc(100% - 9px),0 9px) !important}
[data-wk="bubble"][data-kind="typing"]::before,[data-wk="bubble"][data-kind="typing"]::after{content:none !important}
[data-wk="typingdot"]{width:8px !important;height:8px !important;border-radius:0 !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAxMiAxMic+PHBhdGggZD0nTTYgLjggTDExLjIgNiBMNiAxMS4yIEwuOCA2WicgZmlsbD0nI0M5QTQ1Qycgc3Ryb2tlPScjRUJEMzk0JyBzdHJva2Utd2lkdGg9JzEnLz48L3N2Zz4=") center/contain no-repeat !important}
[data-wk="name"]{color:#C9A45C !important}

/* 动描：不进框——上下两道从中间往两头淡出的金线，上线正中嵌一颗金菱形，字是淡金色楷意斜体 */
[data-wk="narr"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="narrink"]{position:relative !important;display:block !important;background:linear-gradient(90deg,transparent,#8A6A2E 30%,#8A6A2E 70%,transparent) center top/100% 1px no-repeat,linear-gradient(90deg,transparent,#8A6A2E 30%,#8A6A2E 70%,transparent) center bottom/100% 1px no-repeat,radial-gradient(ellipse at 50% 50%,rgba(201,164,92,.10),transparent 70%) !important;border:none !important;border-radius:0 !important;box-shadow:none !important;color:#D9C694 !important;font-style:italic !important;font-family:serif !important;font-size:13px !important;line-height:1.8 !important;letter-spacing:.04em !important;padding:14px 22px !important;text-align:center !important}
[data-wk="narrink"]::before{content:"" !important;position:absolute !important;left:50% !important;top:-5px !important;width:10px !important;height:10px !important;margin-left:-5px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAxMiAxMic+PHBhdGggZD0nTTYgLjggTDExLjIgNiBMNiAxMS4yIEwuOCA2WicgZmlsbD0nI0M5QTQ1Qycgc3Ryb2tlPScjRUJEMzk0JyBzdHJva2Utd2lkdGg9JzEnLz48L3N2Zz4=") center/contain no-repeat !important}
[data-wk="narrink"]::after{content:"" !important;position:absolute !important;left:50% !important;bottom:-5px !important;width:10px !important;height:10px !important;margin-left:-5px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAxMiAxMic+PHBhdGggZD0nTTYgLjggTDExLjIgNiBMNiAxMS4yIEwuOCA2WicgZmlsbD0nIzEyMTAwRCcgc3Ryb2tlPScjQzlBNDVDJyBzdHJva2Utd2lkdGg9JzEnLz48L3N2Zz4=") center/contain no-repeat !important}
/* 系统提示：不带框的一行小字，前面一颗空心金菱 */
[data-wk="sysnote"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="sysnotelabel"]{display:none !important}
[data-wk="sysnotetext"]{background:transparent !important;border:none !important;color:#9C8B66 !important;font-size:11.5px !important;font-style:normal !important;font-family:serif !important;letter-spacing:.08em !important}
[data-wk="sysnotetext"]::before{content:"" !important;display:inline-block !important;width:9px !important;height:9px !important;margin-right:6px !important;vertical-align:0 !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAxMiAxMic+PHBhdGggZD0nTTYgMS4yIEwxMC44IDYgTDYgMTAuOCBMMS4yIDZaJyBmaWxsPSdub25lJyBzdHJva2U9JyNDOUE0NUMnIHN0cm9rZS13aWR0aD0nMS4zJy8+PC9zdmc+") center/contain no-repeat !important}
[data-wk="sysnoteclose"]{color:#9C8B66 !important}

/* 底栏：墨底，上沿一条回纹金带；输入框是墨底金边的长八角 */
[data-wk="composer"]{background:linear-gradient(180deg,#1D1A15,#0C0B09) !important;border-top:none !important;position:relative !important;overflow:visible !important;align-items:center !important;gap:8px !important}
[data-wk="composer"]::before{content:"" !important;position:absolute !important;left:0 !important;right:0 !important;bottom:100% !important;height:12px !important;background:url("data:image/svg+xml;base64,") 0 0/24px 12px repeat-x !important;transform:scaleY(-1) !important;pointer-events:none !important}
[data-wk="chatinput"]{background:linear-gradient(#8A6A2E,#8A6A2E) left bottom/100% 1.2px no-repeat,#2A251D !important;border:none !important;border-radius:0 !important;clip-path:polygon(8px 0,calc(100% - 8px) 0,100% 8px,100% calc(100% - 8px),calc(100% - 8px) 100%,8px 100%,0 calc(100% - 8px),0 8px) !important;color:#F2E6C8 !important}
[data-wk="chatinput"]::placeholder{color:#9C8B66 !important}
[data-wk="chatplus"],[data-wk="send"]{width:34px !important;min-width:34px !important;height:34px !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background-color:transparent !important}
[data-wk="chatplus"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="send"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;opacity:1 !important}
[data-wk="chatreply"]{position:relative !important;width:64px !important;min-width:64px !important;height:34px !important;border:none !important;border-radius:0 !important;clip-path:polygon(9px 0,calc(100% - 9px) 0,100% 9px,100% calc(100% - 9px),calc(100% - 9px) 100%,9px 100%,0 calc(100% - 9px),0 9px) !important;background:#C9A45C !important;box-shadow:none !important}
[data-wk="chatreply"]::before{content:"回复" !important;position:absolute !important;inset:1.6px !important;clip-path:polygon(8.3px 0,calc(100% - 8.3px) 0,100% 8.3px,100% calc(100% - 8.3px),calc(100% - 8.3px) 100%,8.3px 100%,0 calc(100% - 8.3px),0 8.3px) !important;display:flex !important;align-items:center !important;justify-content:center !important;background:linear-gradient(180deg,#2A251D,#1D1A15) !important;color:#EBD394 !important;font-size:13px !important;font-family:serif !important;letter-spacing:.2em !important}
[data-wk="chatplus"] *,[data-wk="send"] *,[data-wk="chatreply"] *{opacity:0 !important}
[data-wk="chatplus"]:active,[data-wk="send"]:active,[data-wk="chatreply"]:active{transform:scale(.9) !important}
[data-wk="chatpanel"]{background:#1D1A15 !important;border-top:1.4px solid #8A6A2E !important}
